<?php
declare(strict_types=1);
use App\Models\{Club, User}; use App\Services\Finance\ClubOrdinaryIncomeReceiptService; use App\Services\Finance\Exceptions\ClubOrdinaryIncomeReceiptConflictException;
require dirname(__DIR__, 2).'/vendor/autoload.php'; $app = require dirname(__DIR__, 2).'/bootstrap/app.php'; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); [$requestPath, $barrier, $worker] = array_slice($argv, 1); $request = json_decode((string) file_get_contents($requestPath), true, flags: JSON_THROW_ON_ERROR); file_put_contents($barrier.DIRECTORY_SEPARATOR."ready.{$worker}", '1'); $deadline = microtime(true) + 20; while (! file_exists($barrier.DIRECTORY_SEPARATOR.'go')) { if (microtime(true) >= $deadline) throw new RuntimeException('Barrier timeout.'); usleep(10000); }
try { $receipt = app(ClubOrdinaryIncomeReceiptService::class)->record(Club::findOrFail($request['club']), User::findOrFail($request['actor']), $request['payload']); $result = ['status' => 'success', 'receipt' => $receipt->public_id, 'journal' => $receipt->journalEntry->public_id]; } catch (ClubOrdinaryIncomeReceiptConflictException) { $result = ['status' => 'conflict', 'code' => 'ORDINARY_INCOME_RECEIPT_IDEMPOTENCY_CONFLICT']; } catch (Throwable $e) { $result = ['status' => 'error', 'class' => $e::class, 'message' => $e->getMessage()]; } file_put_contents($barrier.DIRECTORY_SEPARATOR."result.{$worker}.json", json_encode($result, JSON_THROW_ON_ERROR));
